package com.amicbeam.beyondcraftlines.client.integration.jei;import com.amicbeam.beyondcraftlines.client.DashboardConfigScreen;import com.amicbeam.beyondcraftlines.common.crafting.RecipeResourceResolver;import mezz.jei.api.gui.handlers.IGhostIngredientHandler;import mezz.jei.api.ingredients.ITypedIngredient;import java.util.List;public final class DashboardGhostIngredientHandler implements IGhostIngredientHandler<DashboardConfigScreen>{@Override public <I> List<Target<I>> getTargetsTyped(DashboardConfigScreen screen,ITypedIngredient<I> ingredient,boolean start){var value=RecipeResourceResolver.fromStack(ingredient.getIngredient());if(value==null||value.isEmpty())return List.of();return List.of(new Target<>(){public net.minecraft.client.renderer.Rect2i getArea(){return screen.ghostTargetArea();}public void accept(I ignored){screen.setGhostTarget(value.key());}});}@Override public void onComplete(){}@Override public boolean shouldHighlightTargets(){return true;}}
